import { readFileSync } from "fs";

const lines = readFileSync(0, "utf8").trim().split("\n");
const [h, w] = lines[0].split(" ").map(Number);
const grid = lines.slice(1, h + 1);

const seen = new Uint8Array(h * w);
const stack = new Int32Array(h * w);
let islands = 0;

for (let sy = 0; sy < h; sy++) {
  for (let sx = 0; sx < w; sx++) {
    if (grid[sy][sx] !== "#" || seen[sy * w + sx]) continue;
    // 新しい島を見つけたら、つながる陸をすべて訪問済みにする
    islands++;
    let top = 0;
    stack[top++] = sy * w + sx;
    seen[sy * w + sx] = 1;
    while (top > 0) {
      const cur = stack[--top];
      const y = Math.floor(cur / w);
      const x = cur % w;
      for (const [ny, nx] of [[y - 1, x], [y + 1, x], [y, x - 1], [y, x + 1]]) {
        if (ny < 0 || ny >= h || nx < 0 || nx >= w) continue;
        if (grid[ny][nx] !== "#" || seen[ny * w + nx]) continue;
        seen[ny * w + nx] = 1;
        stack[top++] = ny * w + nx;
      }
    }
  }
}
console.log(islands);
